const formatUTC = (ms) => {
    const date = new Date(ms);
    const hh = String(date.getUTCHours()).padStart(2, '0');
    const mm = String(date.getUTCMinutes()).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    return { time: `${hh}:${mm}`, date: `${day}/${month}` };
};

export function createAirspacePopup(feature, mapContainer, point, reservations = []) {
  const airspaceName = feature.properties.name;
  const lowerFL = feature.properties.lowerFL || '0';
  const upperFL = feature.properties.upperFL || '999';

  const matchingReservations = reservations.filter(res =>
    res.areas?.some(area => area.area_id === airspaceName)
  );

  if (document.querySelector(`[data-airspace="${airspaceName}"]`)) {
    const existingPopup = document.querySelector(`[data-airspace="${airspaceName}"]`);
    const reservationInfo = existingPopup.querySelector('.popup-content div:nth-child(2)');
  
    if (reservationInfo) {
      reservationInfo.innerHTML = '<strong>Reservations:</strong><br/>';
      if (matchingReservations.length === 0) {
        reservationInfo.innerHTML += '[None]';
      } else {
        matchingReservations.forEach(res => {
          const area = res.areas.find(a => a.area_id === airspaceName);
          const startUTC = formatUTC(res.start);
          const endUTC = formatUTC(res.end);
          const line = `#${res.reservation_id}, FL${area.lower} - FL${area.upper}, ${startUTC.time} - ${endUTC.time} on ${startUTC.date}`;
          const resDiv = document.createElement('div');
          resDiv.textContent = line;
          reservationInfo.appendChild(resDiv);
        });
      }
    }
  
    return;
  }

  const popup = document.createElement('div');
  popup.className = 'airspace-popup';
  popup.dataset.airspace = airspaceName;
  popup.style.position = 'fixed';
  popup.style.top = '50%';
  popup.style.right = '30px';

  const topBar = document.createElement('div');
  topBar.className = 'airspace-popup-topBar';

  // Title bar
    const titleBar = document.createElement('div');
    titleBar.className = 'popup-title';
    titleBar.textContent = airspaceName;

    topBar.appendChild(titleBar);

    const closeButton = document.createElement('img');
    closeButton.className = 'popup-close';
    closeButton.src = 'images/close.svg';
    closeButton.alt = 'Close';
    closeButton.onclick = () => popup.remove();

    topBar.appendChild(closeButton);

    popup.appendChild(topBar);

    // Wrapper for content
    const contentWrapper = document.createElement('div');
    contentWrapper.className = 'popup-content';

    // Levels
    const levels = document.createElement('div');
    levels.className = 'popup-levels';
    levels.textContent = `FL${lowerFL} - FL${upperFL}`;
    contentWrapper.appendChild(levels);

    // Reservations
    const reservationInfo = document.createElement('div');
    reservationInfo.innerHTML = '<strong>Reservations:</strong><br/>';

    if (matchingReservations.length === 0) {
    reservationInfo.innerHTML += '[None]';
    } else {
    matchingReservations.forEach(res => {
        const area = res.areas.find(a => a.area_id === airspaceName);
        const startUTC = formatUTC(res.start);
        const endUTC = formatUTC(res.end);
        const line = `#${res.reservation_id}, FL${area.lower} - FL${area.upper}, ${startUTC.time} - ${endUTC.time} on ${startUTC.date}`;
        const resDiv = document.createElement('div');
        resDiv.textContent = line;
        reservationInfo.appendChild(resDiv);
    });
    }

    contentWrapper.appendChild(reservationInfo);
    popup.appendChild(contentWrapper);

  mapContainer.appendChild(popup);

  let isDragging = false;
  let offsetX = 0;
  let offsetY = 0;

  const onMouseDown = (e) => {
    e.preventDefault();
    isDragging = true;

    const rect = popup.getBoundingClientRect();
    offsetX = e.clientX - rect.left;
    offsetY = e.clientY - rect.top;

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  };

  const onMouseMove = (e) => {
    if (!isDragging) return;
    popup.style.left = `${e.clientX - offsetX}px`;
    popup.style.top = `${e.clientY - offsetY}px`;
  };

  const onMouseUp = () => {
    isDragging = false;
    document.removeEventListener('mousemove', onMouseMove);
    document.removeEventListener('mouseup', onMouseUp);
  };

  titleBar.addEventListener('mousedown', onMouseDown);
}

const notifications = [
    { icon: 'images/amcPanel/lam_warning.svg', text: 'LAM Warning' },
    { icon: 'images/amcPanel/activation_action.svg', text: 'Activation Action' },
    { icon: 'images/amcPanel/activation_warning.svg', text: 'Activation Warning' },
    { icon: 'images/amcPanel/reservation_action.svg', text: 'Reservation Action' },
    { icon: 'images/amcPanel/reservation_cancellation.svg', text: 'Reservation Cancellation' },
    { icon: 'images/amcPanel/available_reservation.svg', text: 'Available Reservation' },
    { icon: 'images/amcPanel/reservation_action.svg', text: 'NAM Action' },
    { icon: 'images/amcPanel/reservation_cancellation.svg', text: 'NAM Warning' },
    { icon: 'images/amcPanel/activation_warning.svg', text: 'Release Warning' },
];

export function createAMCPanel(mapContainer, reservations = [], selectedLocation) {

  const notificationCounts = {
    'Activation Action': reservations.filter(r => r.status === 'pending').length,
    'Reservation Cancellation': reservations.filter(r => r.status === 'cancelled').length,
  };

  let panel = document.querySelector('.atc-view-panel');

  if (panel) {
    // Panel exists: update counts only
    notifications.forEach(({ text }) => {
      const row = Array.from(panel.querySelectorAll('.notification-row')).find(r => {
        const label = r.querySelector('span');
        return label && label.textContent === text;
      });
      if (row) {
        const countDiv = row.querySelector('.notification-integer');
        const labelSpan = row.querySelector('span');
        const countValue = notificationCounts[text] || 0;
        if (countDiv) {
          countDiv.textContent = countValue;
          if (countValue > 0) {
            labelSpan.style.color = '#fff';
            countDiv.style.color = '#fff';
            countDiv.style.fontWeight = 'bold';
          } else {
            labelSpan.style.color = '';
            countDiv.style.color = '';
            countDiv.style.fontWeight = '';
          }
        }
      }
    });
    return;
  }  

  // --- If panel doesn't exist, create it from scratch ---
  panel = document.createElement('div');
  panel.className = 'atc-view-panel';
  panel.style.position = 'fixed';
  panel.style.marginTop = '0px';
  panel.style.marginLeft = '0px';

  // Title Bar
  const titleBar = document.createElement('div');
  titleBar.className = 'atc-panel-titlebar';

  const title = document.createElement('div');
  title.className = 'atc-panel-title';
  title.textContent = 'LARA Notifications: ' + selectedLocation.toUpperCase() + ' AMC';

  const chevron = document.createElement('div');
  chevron.className = 'atc-panel-chevron';
  chevron.innerHTML = '▼';

  titleBar.appendChild(title);
  titleBar.appendChild(chevron);
  panel.appendChild(titleBar);

  // Content Wrapper
  const contentWrapper = document.createElement('div');
  contentWrapper.className = 'atc-panel-content';

  notifications.forEach(({ icon, text }) => {
    const row = document.createElement('div');
    row.className = 'notification-row';

    const left = document.createElement('div');
    left.className = 'notification-left';

    const img = document.createElement('img');
    img.src = icon;
    img.alt = text;
    img.className = 'notification-icon';

    const label = document.createElement('span');
    label.textContent = text;

    left.appendChild(img);
    left.appendChild(label);

    const countValue = notificationCounts[text] || 0;

    const count = document.createElement('div');
    count.className = 'notification-integer';
    count.textContent = countValue;

    if (countValue > 0) {
        label.style.color = '#fff';
        count.style.color = '#fff';
        count.style.fontWeight = 'bold';
    }

    row.appendChild(left);
    row.appendChild(count);
    contentWrapper.appendChild(row);
  });
  
  panel.appendChild(contentWrapper);

  let isCollapsed = true;
  contentWrapper.style.display = 'none';
  chevron.innerHTML = '▲';

  chevron.onclick = () => {
    isCollapsed = !isCollapsed;
    contentWrapper.style.display = isCollapsed ? 'none' : 'block';
    chevron.innerHTML = isCollapsed ? '▲' : '▼';
  };

  mapContainer.appendChild(panel);
}
