import React, { useEffect, useRef, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';
import { RESERVATIONS_URL, getGeojsonFile } from '../config';
import { useLocation } from './AreaContext';
import { createAirspacePopup, createAMCPanel } from './AirspacePopup';

mapboxgl.accessToken = 'pk.eyJ1Ijoib3R0b3R1aGt1bmVuIiwiYSI6ImNtcTZmNGEwMzAwczMycXM4aTFxdHY1aHMifQ.PIu8gMrWclqx9Zx_eYBTsg';

const debounce = (func, wait) => {
  let timeout;
  return (...args) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func.apply(this, args), wait);
  };
};

const Map = ({ view, jsonData }) => {
  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const reservationsRef = useRef([]);
  const [intervalId, setIntervalId] = useState(null);
  const [airspaceData, setAirspaceData] = useState(null);
  const [mapCenter, setMapCenter] = useState([25.3340, 64.9631]);
  const [mapZoom, setMapZoom] = useState(4.1);
  const { selectedLocation } = useLocation(); 

  useEffect(() => {
    async function fetchData() {
      try {
        const geojsonResponse = await fetch(getGeojsonFile(selectedLocation));
        if (!geojsonResponse.ok) throw new Error('Failed to load GeoJSON');
        const geojsonData = await geojsonResponse.json();
  
        setAirspaceData(geojsonData);
        setMapCenter(jsonData.mapCenter);
        setMapZoom(jsonData.mapZoom);
      } catch (error) {
        console.error(error);
      }
    }
  
    fetchData();
  }, [selectedLocation]);

  useEffect(() => {
    if (!airspaceData || !selectedLocation) return;
    
    const map = new mapboxgl.Map({
      container: mapContainerRef.current,
      style: 'mapbox://styles/ottotuhkunen/cm9482kdv009q01qze3le3bdi',
      center: mapCenter,
      zoom: mapZoom,
      pitch: 0,
      maxPitch: 0,
      bearing: 0,
      maxBearing: 0
    });

    mapRef.current = map;

    let zoomLabel = null;

    // show zoom level for EACC
    if (selectedLocation === 'eacc') {
      zoomLabel = document.createElement('div');
      zoomLabel.style.cssText = `
        position: absolute;
        top: 2px;
        left: 6px;
        color: white;
        font-size: 12px;
        z-index: 10;
      `;
      zoomLabel.innerText = `Zoom: ${map.getZoom().toFixed(2)}`;
      mapContainerRef.current.appendChild(zoomLabel);
    
      map.on('zoom', () => {
        zoomLabel.innerText = `Zoom: ${map.getZoom().toFixed(2)}`;
      });
    }    

    const handleResize = debounce(() => {
      map.resize();
    }, 200);

    const observer = new ResizeObserver(handleResize);
    observer.observe(mapContainerRef.current);

    window.addEventListener('resize', handleResize);

    map.on('load', async () => {
      const geojson = airspaceData;

      map.addSource('efin-areas', {
        type: 'geojson',
        data: geojson
      });

      map.addLayer({
        id: 'efin-fill',
        type: 'fill',
        source: 'efin-areas',
        paint: {
          'fill-color': 'transparent',
        }
      });

      map.addLayer({
        id: 'efin-outline',
        type: 'line',
        source: 'efin-areas',
        paint: {
          'line-color': '#aaa',
          'line-width': 2.5,
          'line-opacity': 0.1,
          'line-offset': 2,
        }
      });

      map.addLayer({
        id: 'efin-outline-outer',
        type: 'line',
        source: 'efin-areas',
        paint: {
          'line-color': '#aaa',
          'line-width': 0.6,
        }
      });

      map.addLayer({
        id: 'efin-labels',
        type: 'symbol',
        source: 'efin-areas',
        layout: {
          'text-field': ['get', 'name'],
          'text-size': 10,
          'text-anchor': 'left'
        },
        paint: {
          'text-color': 'white',
          'text-halo-color': 'black',
          'text-halo-width': 4
        },
        filter: ['in', ['get', 'status'], ['literal', ['active', 'reserved', 'pending']]] // initially hidden
      });

      const updateAreas = async () => {
        try {
          const response = await fetch(`${RESERVATIONS_URL}combined.json`);
          const reservations = await response.json();
      
          // 1) Normal filtering
          const filtered = reservations.filter(r =>
            r.location.includes(selectedLocation)
          );

          // 2) Cross-border areas (only if selectedLocation === "efin")
          let crossBorder = [];
          crossBorder = reservations.flatMap(res =>
            (res.areas || [])
              .filter(area => area.foreignClusters?.includes(selectedLocation))
              .map(area => ({
                reservation_id: res.reservation_id,
                status: res.status,
                // Include the reservation-level start/end times
                start: area.start_time ?? res.start, 
                end: area.end_time ?? res.end,
                area: {
                  ...area,
                  start: area.start_time ?? res.start,
                  end: area.end_time ?? res.end
                }
              }))
          );
      
          // Keep reference of the normal reservations
          reservationsRef.current = [
            ...filtered,
            ...crossBorder.map(f => ({
              ...f,
              areas: [f.area]
            }))
          ];
      
          if (view === "ATCView" && mapRef.current) {
            createAMCPanel(mapRef.current.getContainer(), filtered, selectedLocation);
          }
      
          const normalizeCoords = (coords) => Array.isArray(coords[0][0][0]) ? coords[0] : coords;

          const features = [
            ...filtered.flatMap(res =>
              (res.areas || []).map(area => ({
                type: "Feature",
                geometry: { type: "Polygon", coordinates: normalizeCoords(area.coordinates) },
                properties: { reservation_id: res.reservation_id, name: area.area_id, status: res.status }
              }))
            ),
          
            ...reservations.flatMap(res =>
              (res.areas || [])
                .filter(area => area.foreignClusters?.length)
                .map(area => ({
                  type: "Feature",
                  geometry: { type: "Polygon", coordinates: normalizeCoords(area.coordinates) },
                  properties: { reservation_id: res.reservation_id, name: area.area_id, status: res.status }
                }))
            )
          ];        
      
          const geojson = {
            type: "FeatureCollection",
            features
          };
      
          if (map.getSource("reservation-areas")) {
            map.getSource("reservation-areas").setData(geojson);
          } else {
            map.addSource("reservation-areas", {
              type: "geojson",
              data: geojson
            });
      
            // Fill layer
            map.addLayer({
              id: "reservation-fill",
              type: "fill",
              source: "reservation-areas",
              paint: {
                "fill-color": [
                  "match",
                  ["get", "status"],
                  "active",
                  "rgba(255, 0, 0, 0.3)",
                  "reserved",
                  "transparent",
                  "pending",
                  "transparent",
                  "transparent"
                ]
              }
            });
      
            // Outline layer
            map.addLayer({
              id: "reservation-outline",
              type: "line",
              source: "reservation-areas",
              paint: {
                "line-color": [
                  "match",
                  ["get", "status"],
                  "active",
                  "red",
                  "reserved",
                  "#0492c2",
                  "pending",
                  "orange",
                  "#aaa"
                ],
                "line-width": 2.5,
                "line-opacity": [
                  "case",
                  ["in", ["get", "status"], ["literal", ["active", "reserved", "pending"]]],
                  0.8,
                  0.1
                ]
              }
            });
      
            // Labels
            map.addLayer({
              id: "reservation-labels",
              type: "symbol",
              source: "reservation-areas",
              layout: {
                "text-field": ["get", "name"],
                "text-size": 10,
                "text-anchor": "left"
              },
              paint: {
                "text-color": "white",
                "text-halo-color": "black",
                "text-halo-width": 4
              },
              filter: ["in", ["get", "status"], ["literal", ["active", "reserved", "pending"]]]
            });
          }
        } catch (err) {
          console.error("Error fetching reservations:", err);
        }
      };         

      await updateAreas();
      const id = setInterval(updateAreas, 120000);
      setIntervalId(id);

      // UI: Reset button
      const resetButton = document.createElement('button');
      resetButton.innerText = 'Reset';
      resetButton.className = 'reset-button';
      mapContainerRef.current.appendChild(resetButton);

      resetButton.onclick = () => {
        map.flyTo({ center: jsonData.mapCenter, zoom: jsonData.mapZoom });
      };

      // UI: Crosshair
      const plusSymbol = document.createElement('div');
      plusSymbol.innerHTML = '+';
      Object.assign(plusSymbol.style, {
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        fontSize: '24px',
        color: 'gray',
        pointerEvents: 'none',
        display: 'none',
        zIndex: 1
      });
      mapContainerRef.current.appendChild(plusSymbol);

      let isDragging = false;
      map.on('dragstart', () => {
        isDragging = true;
        plusSymbol.style.display = 'block';
      });
      map.on('dragend', () => {
        isDragging = false;
        plusSymbol.style.display = 'none';
      });

      // UI: Coordinate window
      const coordsDiv = document.createElement('div');
      coordsDiv.className = 'coordinates';
      coordsDiv.innerHTML = `DMS 64°57'47''N 025°20'02''E`;
      mapContainerRef.current.appendChild(coordsDiv);

      const convertToDMS = (coord, type) => {
        const abs = Math.abs(coord);
        const deg = Math.floor(abs);
        const min = Math.floor((abs - deg) * 60);
        const sec = Math.round((abs - deg - min / 60) * 3600);
        const dir = type === 'lat' ? (coord >= 0 ? 'N' : 'S') : (coord >= 0 ? 'E' : 'W');
        return `${type === 'lng' ? String(deg).padStart(3, '0') : String(deg).padStart(2, '0')}°${String(min).padStart(2, '0')}'${String(sec).padStart(2, '0')}''${dir}`;
      };

      const updateCoordinates = (lngLat) => {
        const lat = convertToDMS(lngLat.lat, 'lat');
        const lng = convertToDMS(lngLat.lng, 'lng');
        coordsDiv.innerHTML = `DMS ${lat} ${lng}`;
      };

      map.on('move', () => {
        if (!isDragging) plusSymbol.style.display = 'none';
        updateCoordinates(map.getCenter());
      });

      // Controls
      map.addControl(new mapboxgl.ScaleControl({ maxWidth: 80, unit: 'nautical' }));
      map.addControl(new mapboxgl.NavigationControl());
      map.dragRotate.disable();
      map.touchZoomRotate.disableRotation();

      // Change cursor to pointer when hovering over features with a name
      map.on('mousemove', (e) => {
        const features = map.queryRenderedFeatures(e.point, {
          layers: ['efin-fill', 'reservation-fill'],
        });
        const hasName = features.some(f => f.properties?.name?.trim());
        map.getCanvas().style.cursor = hasName ? 'pointer' : '';
      });
      
      // Handle click to open popup
      map.on('click', (e) => {
        const features = map.queryRenderedFeatures(e.point, {
          layers: ['efin-fill', 'reservation-fill'],
        });

        if (!features.length) return;

        features.forEach((feature) => {
          const name = feature.properties?.name?.trim();
          if (name) {
            createAirspacePopup(feature, map.getContainer(), e.point, reservationsRef.current);
          }
        });
      });
    });

    return () => {
      if (intervalId) clearInterval(intervalId);
      observer.disconnect();
      window.removeEventListener('resize', handleResize);
      if (mapRef.current) mapRef.current.remove();
      if (zoomLabel) zoomLabel.remove();
    };
  }, [airspaceData, selectedLocation]);

  return (
    <div
      ref={mapContainerRef}
      style={{ width: '100%', height: '100%', position: 'relative', zIndex: 1 }}
    />
  );
};

export default Map;
